import{z as A,x as l,o as r,c as p,q as m,j as E,D as t,d as o,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"Merton 组合问题","description":"","frontmatter":{"title":"Merton 组合问题","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/merton-portfolio-theory.md","filePath":"econ/merton-portfolio-theory.md","lastUpdated":1791063341000}'),d={name:"econ/merton-portfolio-theory.md"};function B(h,a,c,u,C,_){const n=l("Mermaid");return r(),p("div",null,[a[2]||(a[2]=m('<h1 id="merton-组合问题" tabindex="-1">Merton 组合问题 <a class="header-anchor" href="#merton-组合问题" aria-label="Permalink to &quot;Merton 组合问题&quot;">​</a></h1><div class="epigraph"><p>常投资机会下，最优是瞬时均值–方差切点加消费；权重对财富的比例由风险厌恶钉住，对冲还没有出场。</p><footer>—— Merton, Lifetime Portfolio Selection under Uncertainty: the Continuous-Time Case, Review of Economics and Statistics, 1969；JET 1971</footer></div><p><a href="/econ/continuous-time-budget">上一课</a>写好了 \\(\\mathrm{d}W\\)。本课缺口是最优：在常系数 \\((\\mu,r,\\sigma)\\) 下选 \\((c_t,\\theta_t)\\) 最大化时间可分期望效用。主干 <a href="/econ/icapm-merton">ICAPM</a> 已经用过「机会随机则多对冲」；本课先把机会钉死，得到教科书 Merton 权重。不重写 ICAPM 的多 beta，不估计股票债券比例。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无限（或有限）生命，\\(\\mathrm{E}\\int_0^T e^{-\\rho t}u(c_t)\\,\\mathrm{d}t\\)（可加遗产）。状态只要 \\(W\\)，因为 \\((\\mu,r,\\sigma)\\) 不是状态。HJB：值函数 \\(J(W)\\)，一阶条件给出</p> \\[\\theta^\\ast=\\frac{\\mu-r}{\\gamma(W)\\,\\sigma^2},\\qquad u&#39;(c)=J_W, \\]<p>其中 \\(\\gamma(W)=-W J_{WW}/J_W\\) 为相对风险厌恶（值函数的）。CRRA 时 \\(\\theta\\) 为常数、\\(c\\) 与 \\(W\\) 成比例。缺口是：这是连续时间里均值方差切点的精确化——机会确定，不必对冲。后课才把 \\(r\\) 或 \\(\\mu\\) 变成状态。</p><p><span class="marginnote">数字代入：取超额回报 \\(\\mu-r=6\\%\\)、波动 \\(\\sigma=20\\%\\)、风险厌恶 \\(\\gamma=3\\)，则 \\(\\theta^\\ast=0.06/(3\\times 0.04)=0.5\\)，一半财富放风险资产；若 \\(\\gamma\\) 升到 6，比例立刻减半到 25%。公式只有三个输入，手算就能得到配置。</span></p><p>与离散均值方差课对照：那里 MV=EU 需要二次或正态；这里扩散加时间可分，瞬时问题就是 MV，伊藤把高阶瞬间变成 \\(\\mathrm{d}t\\) 的高阶无穷小。许可证来自连续时间装置，不是二次效用。</p><p><span class="marginnote">Merton, <em>REStat</em> 1969；<em>JET</em> 1971。CARA 对财富的绝对需求，CRRA 对比例需求。本课以 CRRA 为工作形状，与主干偏好课一致。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>HJB 对 \\(\\theta,c\\) 点态最大化，把预算的漂移与扩散代入生成元。包络：\\(J_W\\) 是财富的影子价格，消费欧拉是 \\(u&#39;(c)\\) 沿最优财富的伊藤过程为鞅（差折现）。组合的一阶是「超额回报对边际效用的协方差」瞬时版——与 <a href="/econ/stochastic-discount-factor">SDF</a> 的 \\(0=\\mathrm{E}[m R^e]\\) 同一句话，测度换成无穷小。</p>',12)),(r(),E(s,null,{default:t(()=>[i(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUD%5B%22%E9%A2%84%E7%AE%97%20SDE%22%5D%20--%3E%20HJB%5B%22HJB%3A%20%E7%8A%B6%E6%80%81%E5%8F%AA%E6%9C%89%20W%22%5D%0A%20%20HJB%20--%3E%20TH%5B%22%CE%B8*%20%3D%20(%CE%BC-r)%2F(%CE%B3%20%CF%83%C2%B2)%22%5D%0A%20%20HJB%20--%3E%20C%5B%22u'(c)%20%3D%20J_W%22%5D%0A%20%20TH%20--%3E%20MY%5B%22%E7%9E%AC%E6%97%B6%E5%88%87%E7%82%B9%2C%20%E6%97%A0%E5%AF%B9%E5%86%B2%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"完全市场：一个布朗、一个风险资产，任意终端消费可复制，个人问题良定。不完全：\\(\\theta\\) 张不成所有暴露，HJB 仍可写，但达不到第一优——定价界后课。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是瞬时切点与消费分离。机会确定时，财富是唯一状态，组合只为了这瞬间的均值方差（对 \\(J\\) 而言），消费只为了摊平 \\(u'(c)\\) 与 \\(J_W\\)。两基金：无风险加切点基金。加总若人人同此且同质信念，市场即切点——下一课连续时间 CAPM。本课还不出清，只单人。",-1)),(r(),E(s,null,{default:t(()=>[i(n,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20LR%0A%20%20EX%5B%22%E8%B6%85%E9%A2%9D%E5%9B%9E%E6%8A%A5%20%CE%BC%E2%88%92r%20%E5%8F%98%E5%A4%A7%22%5D%20--%3E%20BIG%5B%22%CE%B8*%20%E5%8F%98%E5%A4%A7%22%5D%0A%20%20VOL%5B%22%E6%B3%A2%E5%8A%A8%20%CF%83%C2%B2%20%E5%8F%98%E5%A4%A7%22%5D%20--%3E%20SMALL%5B%22%CE%B8*%20%E5%8F%98%E5%B0%8F%22%5D%0A%20%20GAMMA%5B%22%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%20%CE%B3%20%E5%8F%98%E5%A4%A7%22%5D%20--%3E%20SMALL%0A%20%20BIG%20--%3E%20MIX%5B%22%E9%A3%8E%E9%99%A9%E8%B5%84%E4%BA%A7%E5%8D%A0%E8%B4%A2%E5%AF%8C%E7%9A%84%E6%AF%94%E4%BE%8B%22%5D%0A%20%20SMALL%20--%3E%20MIX%0A%20%20MIX%20--%3E%20SEP%5B%22CRRA%20%E4%B8%8B%3A%20%E6%AF%94%E4%BE%8B%E4%B8%8E%E8%B4%A2%E5%AF%8C%E5%A4%9A%E5%B0%91%E6%97%A0%E5%85%B3%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=m('<p><span class="marginnote">两基金定理的直觉：不管你想承担多少风险，都只需在「无风险存款」与同一只「切点基金」之间挪动比例，而不必另挑一只不同的基金。投资者之间的差别只体现在这条线上各自站的位置，不在基金本身——这就是「分离」二字的含义。</span></p><p>\\(\\gamma\\) 若随 \\(W\\) 变（非 CRRA），\\(\\theta\\) 随财富变，加总困难——Gorman 加总在连续时间同样刀刃。工作模型常用 CRRA 正是为了比例需求。</p><p><span class="marginnote">有限生命的确定性等价仍比例于 \\(W\\)（CRRA），但消费率随剩余寿命变。无限生命更干净：政策平稳。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 \\(\\theta^\\ast\\) 写成「股票配置 60%」的建议。\\((\\mu,\\sigma)\\) 不是本栏估计对象。下一课打开机会集：状态 \\(z\\) 进入 \\(J(W,z)\\)，一阶条件多出 \\(J_{Wz}\\) 项——对冲需求的来源。ICAPM 主干已经报过结果；后课写来源，不重写截面。</p><p><span class="marginnote">初学者容易把 \\(\\theta^\\ast\\) 当成用历史平均收益套出来的固定推荐。实际上 \\(\\mu,\\sigma\\) 是外生给定的模型输入，不是估计对象；而且机会一旦随时间变化，最优权重还要加上一项对冲需求，本课的常数只是「机会冻结」的特例。</span></p><p>后课默认：常机会下 Merton 权重是瞬时切点，消费由 \\(J_W\\) 给出。无对冲项。CRRA 使 \\(\\theta\\) 为常数。这是组合理论，不是 CAPM 实证。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>常 \\((\\mu,r,\\sigma)\\)：\\(\\theta^\\ast=(\\mu-r)/(\\gamma\\sigma^2)\\)，\\(u&#39;(c)=J_W\\)。</li><li>瞬时问题是均值方差，因为扩散把更高阶变成 \\(o(\\mathrm{d}t)\\)。</li><li>尚未出清，尚未对冲；两基金只在单人问题里。</li><li>出处：Merton, <em>REStat</em> 1969；<em>JET</em> 1971。</li></ul>',9))])}const g=A(d,[["render",B]]);export{M as __pageData,g as default};
